# Generated by build.py from recipe.yml for recipe sftp-list-and-make-folders. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--throwaway-hostkey', '--user', 'alice:s3cret', '--list-directories', '--allow-uploads', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -S -k -u alice:s3cret -Q "mkdir /reports" -l sftp://127.0.0.1:8080/ } finally { Stop-Process $server0 }
